    crossReferenceParts: [ { partName: "Ignition Coil", category: "Ignition", oem: { brand: "Audi Genuine", code: "04E 905 110 K", approxPrice: "65 EUR" }, crossRef: { brand: "Eldor", code: "R3516S00100", approxPrice: "32 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=R3516S00100", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Ignition+Coil+Audi+A1+1.0+TFSI&storeId=10151&catalogId=10051&langId=-1" }, note: "Eldor is the Turkish supplier that solved the early coil failures on TSI engines. This is the exact factory part." }, { partName: "Water Pump / Thermal Module", category: "Cooling", oem: { brand: "Audi Genuine", code: "04E 121 600 P", approxPrice: "280 EUR" }, crossRef: { brand: "INA", code: "538 0363 10", approxPrice: "140 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=538036310", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Water+Pump+Audi+A1+1.0+TFSI&storeId=10151&catalogId=10051&langId=-1" }, note: "INA (Schaeffler) manufactures this complex thermal management module for VAG. Buying the INA box saves 50%." }, { partName: "Spark Plug", category: "Ignition", oem: { brand: "Audi Genuine", code: "04E 905 601 B", approxPrice: "24 EUR" }, crossRef: { brand: "NGK", code: "PZKER7A8EGS", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=PZKER7A8EGS", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=NGK+PZKER7A8EGS&storeId=10151&catalogId=10051&langId=-1" }, note: "These plugs are indexed (the thread stops at a specific point) so the electrode faces the injector. Only NGK or Bosch specific codes work correctly." }, { partName: "Turbo Wastegate Actuator", category: "Turbocharger", oem: { brand: "Audi Genuine", code: "04E 145 725 AB", approxPrice: "250 EUR" }, crossRef: { brand: "Mahle", code: "030 TC 11002 000", approxPrice: "130 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=Mahle", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Turbo+Actuator+Audi+A1&storeId=10151&catalogId=10051&langId=-1" }, note: "Mahle produces the electric actuator. Common failure point. Buying the Mahle part avoids buying a whole new turbo from Audi." }, { partName: "Oil Filter", category: "Maintenance", oem: { brand: "Audi Genuine", code: "04E 115 561 H", approxPrice: "18 EUR" }, crossRef: { brand: "Mann-Filter", code: "W 712/95", approxPrice: "9 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=W71295", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Mann+W712/95&storeId=10151&catalogId=10051&langId=-1" }, note: "Mann supplies the factory filters. Includes the correct anti-drain back valve required for the variable oil pump." }, { partName: "Timing Belt Kit", category: "Engine", oem: { brand: "Audi Genuine", code: "04E 198 119", approxPrice: "180 EUR" }, crossRef: { brand: "Continental", code: "CT1167K1", approxPrice: "85 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=CT1167K1", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Timing+Belt+Kit+Audi+A1+1.0&storeId=10151&catalogId=10051&langId=-1" }, note: "ContiTech supplies the belts for the EA211 assembly line. The kit includes the tensioner and idler which must be replaced." }, { partName: "Front Brake Discs (256mm)", category: "Brakes", oem: { brand: "Audi Genuine", code: "1J0 615 301 N", approxPrice: "160 EUR / pair" }, crossRef: { brand: "ATE", code: "24.0122-0151.1", approxPrice: "70 EUR / pair", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=24012201511", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=ATE+Brake+Disc+Audi+A1&storeId=10151&catalogId=10051&langId=-1" }, note: "Standard VW Group 256mm rotors. ATE creates the calipers and discs for the A1 platform." }, { partName: "Lambda Sensor (Pre-Cat)", category: "Sensors", oem: { brand: "Audi Genuine", code: "04E 906 262 AG", approxPrice: "220 EUR" }, crossRef: { brand: "Bosch", code: "0 258 027 063", approxPrice: "95 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=0258027063", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Bosch+Oxygen+Sensor+Audi+A1&storeId=10151&catalogId=10051&langId=-1" }, note: "Broadband 5-wire sensor. Bosch is the original manufacturer. Crucial for fuel economy." }, { partName: "High Pressure Fuel Pump", category: "Fuel System", oem: { brand: "Audi Genuine", code: "04E 127 026 CDP", approxPrice: "350 EUR" }, crossRef: { brand: "Hitachi / Hüco", code: "133072", approxPrice: "180 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=133072", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Hitachi+Fuel+Pump+Audi+A1&storeId=10151&catalogId=10051&langId=-1" }, note: "Hitachi supplies the fuel system for the 1.0 TFSI. Identical part." }, { partName: "Clutch Kit (Manual)", category: "Transmission", oem: { brand: "Audi Genuine", code: "04E 141 016 K", approxPrice: "350 EUR" }, crossRef: { brand: "Sachs", code: "3000 950 094", approxPrice: "160 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=3000950094", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Sachs+Clutch+Kit+Audi+A1&storeId=10151&catalogId=10051&langId=-1" }, note: "Sachs manufactures the clutch and pressure plate for the MQ200 gearbox." } ],
    sisterModels: [ { name: "Volkswagen Polo (6C/6R) 1.0 TSI", note: "Mechanical twin. Shares the entire drivetrain, suspension, and electronics architecture." }, { name: "Seat Ibiza (6J/6P) 1.0 TSI", note: "Same EA211 engine and MQ200 gearbox. Lighter chassis but less sound insulation." }, { name: "Skoda Fabia III (NJ) 1.0 TSI", note: "Uses the same DKLD engine code. Parts interchangeability is near 100% for engine bay components." }, { name: "Audi A3 (8V) 1.0 TFSI", note: "The entry level A3 uses a slightly tuned version of this engine (115hp), but the block and head are identical." }, { name: "Volkswagen Golf VII 1.0 TSI", note: "Found in the BlueMotion variants. Identical thermal management and injection system." } ],
