    crossReferenceParts: [ { partName: "Timing Chain Kit", category: "Engine", oem: { brand: "Audi Genuine", code: "03F 198 158 B", approxPrice: "200 EUR" }, crossRef: { brand: "INA", code: "559 0114 10", approxPrice: "110 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=559011410", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Timing+Chain+Kit+Audi+1.2+TFSI" }, note: "Must be the latest revision 'B' to prevent stretching. Includes gears and tensioner." }, { partName: "Ignition Lead Set", category: "Ignition", oem: { brand: "Audi Genuine", code: "03F 905 409 C", approxPrice: "80 EUR" }, crossRef: { brand: "NGK", code: "44303", approxPrice: "40 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=44303", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Ignition+Leads+Audi+1.2+TFSI" }, note: "Crucial upgrade. High quality silicone leads prevent arcing and misfires common with OEM rubber leads." }, { partName: "Ignition Coil Block", category: "Ignition", oem: { brand: "Audi Genuine", code: "03F 905 100 B", approxPrice: "120 EUR" }, crossRef: { brand: "Bosch", code: "0 986 221 057", approxPrice: "60 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=0986221057", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Ignition+Coil+Audi+1.2+TFSI" }, note: "Single block design. Inspect for hairline cracks on the casing which cause damp weather misfires." }, { partName: "Spark Plug", category: "Ignition", oem: { brand: "Audi Genuine", code: "101 905 601 F", approxPrice: "20 EUR" }, crossRef: { brand: "NGK", code: "IZFR6P7", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=IZFR6P7", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=NGK+IZFR6P7" }, note: "Iridium LongLife plugs. Essential for the high combustion temperatures of this small turbo engine." }, { partName: "Water Pump", category: "Cooling", oem: { brand: "Audi Genuine", code: "03F 121 004 E", approxPrice: "150 EUR" }, crossRef: { brand: "INA", code: "538 0055 10", approxPrice: "70 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=538005510", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Water+Pump+Audi+1.2+TFSI" }, note: "Belt driven pump, separate from the timing chain. Check for pulley wobble." }, { partName: "Fuel Filter", category: "Fuel", oem: { brand: "Audi Genuine", code: "6Q0 201 051 C", approxPrice: "30 EUR" }, crossRef: { brand: "Mann-Filter", code: "WK 69/2", approxPrice: "15 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=WK692", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Mann+WK692" }, note: "Includes built-in 4.0 bar pressure regulator. Do not install generic filters without regulator." }, { partName: "Oil Filter", category: "Maint", oem: { brand: "Audi Genuine", code: "03C 115 561 D", approxPrice: "15 EUR" }, crossRef: { brand: "Mann-Filter", code: "W 712/94", approxPrice: "8 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=W71294", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Mann+W712/94" }, note: "High quality anti-drain back valve prevents dry starts, helping chain tensioner longevity." }, { partName: "Turbo Wastegate Clip", category: "Turbo", oem: { brand: "Audi Genuine", code: "06J 145 220 A", approxPrice: "15 EUR" }, crossRef: { brand: "Febi", code: "108200", approxPrice: "5 EUR", source: "Aftermarket", autodoclink: "https://www.autodoc.parts/search?keyword=06J145220A", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Wastegate+Clip+Audi" }, note: "Simple metal clip that reduces wastegate rod rattle noise. Highly recommended fix." }, { partName: "Front Brake Pads", category: "Brakes", oem: { brand: "Audi Genuine", code: "1J0 698 151", approxPrice: "90 EUR" }, crossRef: { brand: "ATE", code: "13.0460-7111.2", approxPrice: "45 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=13046071112", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=ATE+Brake+Pads+Audi+A1" }, note: "Standard pads. Avoid ceramic on this model unless rotors are upgraded, as initial bite is needed." }, { partName: "Battery", category: "Elec", oem: { brand: "Audi Genuine", code: "000 915 105 DE", approxPrice: "150 EUR" }, crossRef: { brand: "Varta", code: "D52", approxPrice: "80 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.parts/search?keyword=Varta+D52", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=Varta+D52" }, note: "Silver Dynamic AGM recommended if Start-Stop is equipped." } ],
