  manualLightPositions: { headlights: { x: 0.55, y: -0.13, z: 1.7 }, taillights: { x: 0.56, y: -0.01, z: -1.71 } }, customLightNames: { headlights: ["Acar_audi_s1sportback_2014_Mesh_lod0M_LightCluster_High_Aphong3SG1_0"], taillights: ["Acar_audi_s1sportback_2014_Mesh_lod0M_LightCluster_High_Aphong3SG1_0"] },
  riskRating: 3, drivingExperience: "The CZDD (EA211) transforms the character of the A1. The aluminum block is 22kg lighter than the old EA111, making the nose feel significantly sharper. The engine is vastly quieter, smoother, and revs more freely. The 125hp feels energetic, and the torque delivery is incredibly linear. The switch to a glass-fiber reinforced timing belt has entirely eliminated the mechanical anxiety associated with older models.", mechanicVerdict: "A vast improvement over the problematic EA111 generation. The EA211 architecture is exceptionally reliable. The primary issue to watch for is the thermal management module (water pump) leaking due to warped plastic housings. It is expensive to replace, but it is a predictable wear item, not catastrophic like the old chain failures. Carbon buildup is still a reality but managed slightly better. Highly recommended as a stress-free daily driver.", repairCostEstimate: "$600 - $800 / year",
  model3DHotspots: [ { x: 0.55, y: 0.10, z: -0.2, label: "Thermal Management Module (Water Pump)", details: "CRITICAL: The water pump housing is made of plastic and frequently warps under heat cycles, causing slow coolant leaks.", critical: true }, { x: 0.0, y: 0.25, z: -0.8, label: "Turbo Wastegate Actuator", details: "CRITICAL: Located at the REAR. The electric actuator rod seizes due to rust. This causes the EPC light to illuminate.", critical: true }, { x: 0.0, y: 0.40, z: 0.6, label: "Intake Manifold (Intercooler)", details: "The water-to-air intercooler is integrated directly into this plastic intake manifold. Check for internal leaks.", critical: false }, { x: 0.0, y: 0.50, z: 0.0, label: "Air Filter Housing", details: "Conveniently located squarely on top of the engine. Extremely easy to service.", critical: false }, { x: -0.45, y: 0.20, z: 0.3, label: "Engine Mount (Hydraulic)", details: "If the steering wheel shakes excessively at idle, this fluid-filled mount has likely collapsed.", critical: false } ],
  engineBayHotspots: [ { x: 0.5, y: 0.5, label: "Engine Oil Fill Cap", details: "Check underneath for thick yellow/white 'mayonnaise' residue.", critical: false }, { x: 0.2, y: 0.2, label: "Engine Oil Dipstick", details: "Check oil level regularly to protect the variable oil pump and turbo.", critical: true }, { x: 0.8, y: 0.2, label: "Coolant Expansion Tank", details: "CRITICAL: Monitor this fluid level meticulously. Any drop indicates the water pump is likely leaking.", critical: true } ],
  visualTechGuide: { views: [ { id: "top_engine_view", label: "Top Engine View", imageUrl: "/images/engines/czca_top.jpg", hotspots: [ { x: 50, y: 20, title: "Airbox", details: "Integrated top-mount airbox for incredibly easy servicing." }, { x: 50, y: 80, title: "Rear Mounted Turbocharger", details: "The turbo is mounted at the very rear for better chassis weight distribution." } ] } ] }
