  timingType: "Belt (Long-life, Glass fiber reinforced)", injectionType: "Direct Injection (High Pressure - 200 Bar)", engineLifespan: "250,000+ km (Robust EA211 architecture)", turboType: "Single Scroll (Integrated Manifold, Rear Mounted)", ecuType: "Bosch Motronic MED 17.5.21", euroStandard: "Euro 6", maxPowerStockInternals: "170 - 180 hp (Limited by tiny Turbo)",
