  commonIssues: [ "Coolant loss (Water pump/Thermostat housing module leak)", "Turbo wastegate actuator seizure (EPC Light / Power Loss)", "Start-Stop System Errors (Battery voltage sensitivity)", "Camshaft adjuster oil leak (Oil seeps into wiring harness)", "Carbon buildup on intake valves (Direct injection characteristic)", "High pressure fuel pump ticking (Normal but can indicate follower wear)", "PCV Valve diaphragm rupture (Causes high-pitched whistling noise)" ],
  vulnerabilities: [ "Water Pump Module - Located on the transmission side, driven by a separate belt. The plastic housing warps and leaks.", "Turbocharger Actuator - The electric actuator rod seizes if not exercised, causing limp mode.", "Manual Clutch - The stock clutch slips early if the engine is tuned beyond 250 Nm.", "DQ200 Mechatronic (if Automatic) - The dry-clutch DSG's brain can fail due to pressure loss.", "PCV Valve Diaphragm - Tears causing whistling noise and lean running codes.", "Internal Intercooler - Integrated into the intake manifold, prone to hidden internal coolant leaks.", "Valve Stem Seals - Can harden over time on high-mileage units, leading to oil consumption." ],
  oemPlusUpgrades: [ { name: "Metal Water Pump Housing", description: "Replacing the warp-prone OEM plastic module with an aftermarket cast-aluminum housing.", benefit: "Permanently solves the notorious EA211 coolant leak issue." }, { name: "Turbo Muffler Delete", description: "Replacing the restrictive OEM turbo muffler with a billet aluminum straight pipe.", benefit: "Improves throttle response and slightly increases turbo spool acoustics." }, { name: "Audi TT / S1 Solid Control Arm Bushings", description: "Replacing the stock 'voided' rubber bushings with solid rubber units from the Audi TT (8J) or S1.", benefit: "Eliminates wheel hop and vague steering feel without ruining comfort." }, { name: "Dogbone Mount Insert", description: "Inserting a polyurethane puck into the factory lower engine pendulum mount.", benefit: "Limits engine rocking during aggressive gear shifts, improving manual shift feel." } ],
  transmission: { manual: { name: "MQ200 (02S) - 6-Speed Manual", torqueLimit: "250 Nm", oilType: "API GL-4 / VW G 052 512 A2", note: "Very lightweight and precise gearbox. Fluid change recommended at 100k km." }, automatics: [ { name: "DQ200 (0CW) - 7-Speed S-Tronic", torqueLimit: "250 Nm", oilType: "G 004 000 (Hydraulic) / G 052 512 (Gear)", note: "Dry Clutch DSG. Mechatronic unit has separate fluid. Clutches wear fast in heavy city traffic." } ] },
