  commonIssues: [ "Coolant loss (Water pump/Thermostat housing module leak)", "Cylinder on Demand (ACT) actuator oil leaks (Oil seeps from the cam actuators on top of the valve cover)", "Turbo wastegate actuator seizure (EPC Light / Power Loss)", "ACT transition shudder (Slight jerk or vibration when switching from 2 to 4 cylinders)", "Carbon buildup on intake valves (Direct injection characteristic)", "Start-Stop System Errors (Battery voltage sensitivity)", "PCV Valve diaphragm rupture (Causes high-pitched whistling noise)" ],
  vulnerabilities: [ "Water Pump Module - Located on the transmission side, driven by a separate belt. The plastic housing warps and leaks.", "ACT Camshaft Actuators - Two solenoids per cylinder (2 and 3) manage the cam profile switching; prone to internal electrical faults or oil leaks.", "Turbocharger Actuator - The electric actuator rod seizes if not exercised, causing limp mode.", "Manual Clutch - The stock clutch slips early if the engine is tuned beyond 280 Nm.", "DQ200 Mechatronic (if Automatic) - The dry-clutch DSG's brain can fail due to pressure loss.", "Internal Intercooler - Integrated into the intake manifold, prone to hidden internal coolant leaks.", "Dual Mass Flywheel - Wear is accelerated due to the unique vibrational harmonics of running in 2-cylinder mode." ],
  oemPlusUpgrades: [ { name: "Metal Water Pump Housing", description: "Replacing the warp-prone OEM plastic module with an aftermarket cast-aluminum housing.", benefit: "Permanently solves the notorious EA211 coolant leak issue." }, { name: "ACT Deactivation Tune", description: "Electronically disabling the Cylinder on Demand system via ECU remap.", benefit: "Prevents 2-cylinder mode vibrations and extends the life of the dual mass flywheel and engine mounts." }, { name: "Audi TT / S1 Solid Control Arm Bushings", description: "Replacing the stock 'voided' rubber bushings with solid rubber units from the Audi TT (8J) or S1.", benefit: "Eliminates wheel hop and vague steering feel without ruining comfort." }, { name: "Turbo Muffler Delete", description: "Replacing the restrictive OEM turbo muffler with a billet aluminum straight pipe.", benefit: "Improves throttle response and slightly increases turbo spool acoustics." } ],
