  InspectionChecklist: [ { id: "water_pump_leak_ea211", category: "Cooling", question: "Is there pink/white crust on the right side of the engine block?", howToCheck: "Look under the intake manifold on the transmission side. The plastic water pump housing warps.", costUSD: 600, costEUR: 550, severity: "HIGH" }, { id: "act_oil_leak", category: "Engine", question: "Is there oil pooling on top of the valve cover?", howToCheck: "Check the black cylindrical ACT actuators on top of the engine. O-rings often leak.", costUSD: 150, costEUR: 120, severity: "MEDIUM" }, { id: "turbo_actuator_epc", category: "Engine", question: "Does the EPC light illuminate during hard acceleration?", howToCheck: "The electric wastegate actuator rod seizes. Scan for OBD code P334A.", costUSD: 450, costEUR: 400, severity: "CRITICAL" }, { id: "dsg_clutch_judder", category: "Transmission", question: "Automatic: Does the car judder or shake on gentle takeoff?", howToCheck: "Drive very slowly in D mode. If it shakes, the dry clutch packs are worn out.", costUSD: 1500, costEUR: 1200, severity: "CRITICAL" }, { id: "clutch_slip_manual", category: "Transmission", question: "Manual: Does the engine RPM rise sharply without the car accelerating?", howToCheck: "Put the car in 4th gear at 40 km/h and floor the throttle.", costUSD: 800, costEUR: 700, severity: "HIGH" }, { id: "idle_roughness", category: "Engine", question: "Is the idle noticeably rough or fluctuating on a cold start?", howToCheck: "Sit in the car with AC off. Shaking indicates carbon buildup on intake valves.", costUSD: 400, costEUR: 350, severity: "MEDIUM" }, { id: "coolant_level_internal", category: "Cooling", question: "Is the coolant level below MIN in the expansion tank?", howToCheck: "The EA211 has an internal water-to-air intercooler. If it leaks internally, the engine burns the coolant.", costUSD: 100, costEUR: 80, severity: "MEDIUM" }, { id: "start_stop_battery", category: "Electronics", question: "Does the Start-Stop system constantly fail to activate?", howToCheck: "Requires a healthy AGM battery. If it never stops the engine, the battery is degraded.", costUSD: 250, costEUR: 200, severity: "LOW" } ],
