  manualLightPositions: { headlights: { x: 0.55, y: -0.13, z: 1.7 }, taillights: { x: 0.56, y: -0.01, z: -1.71 } }, customLightNames: { headlights: ["Acar_audi_s1sportback_2014_Mesh_lod0M_LightCluster_High_Aphong3SG1_0"], taillights: ["Acar_audi_s1sportback_2014_Mesh_lod0M_LightCluster_High_Aphong3SG1_0"] },
  riskRating: 4, drivingExperience: "The CZEA (EA211 ACT) is the most powerful 1.4 variant, offering a highly unique driving experience. It delivers a punchy 150hp and 250Nm of torque, making the A1 feel incredibly fast and responsive. Under light load, it shuts off cylinders 2 and 3 seamlessly to save fuel, giving you hybrid-like efficiency on the highway. The switch is barely noticeable. It's incredibly agile due to the lightweight aluminum block.", mechanicVerdict: "A fantastic engine that blends performance and extreme efficiency. The core EA211 architecture is highly reliable with its belt drive. The ACT system is generally robust, though the actuators can sometimes leak oil. The biggest weakness remains the plastic water pump module. Keep the oil fresh to ensure the delicate ACT solenoids function properly.", repairCostEstimate: "$650 - $850 / year",
  model3DHotspots: [ { x: 0.55, y: 0.10, z: -0.2, label: "Thermal Management Module (Water Pump)", details: "CRITICAL: The water pump housing is made of plastic and frequently warps under heat cycles, causing slow coolant leaks.", critical: true }, { x: 0.0, y: 0.55, z: 0.2, label: "ACT Camshaft Actuators", details: "These solenoids sit on top of the valve cover and shift the cam profiles. Prone to oil leaks from the base O-rings.", critical: false }, { x: 0.0, y: 0.25, z: -0.8, label: "Turbo Wastegate Actuator", details: "CRITICAL: Located at the REAR. The electric actuator rod seizes due to rust. This causes the EPC light to illuminate.", critical: true }, { x: 0.0, y: 0.40, z: 0.6, label: "Intake Manifold (Intercooler)", details: "The water-to-air intercooler is integrated directly into this plastic intake manifold. Check for internal leaks.", critical: false }, { x: -0.45, y: 0.20, z: 0.3, label: "Engine Mount (Hydraulic)", details: "The ACT system places unique vibrations on this mount. If it shakes at idle, it has collapsed.", critical: false } ],
  engineBayHotspots: [ { x: 0.5, y: 0.5, label: "Engine Oil Fill Cap", details: "Check underneath for thick yellow/white 'mayonnaise' residue.", critical: false }, { x: 0.2, y: 0.2, label: "Engine Oil Dipstick", details: "Check oil level regularly. Crucial for the ACT system hydraulics.", critical: true }, { x: 0.8, y: 0.2, label: "Coolant Expansion Tank", details: "CRITICAL: Monitor this fluid level meticulously. Any drop indicates the water pump is likely leaking.", critical: true } ],
  visualTechGuide: { views: [ { id: "top_engine_view", label: "Top Engine View", imageUrl: "/images/engines/czea_top.jpg", hotspots: [ { x: 50, y: 20, title: "ACT Actuators", details: "Visible on top of the engine block." }, { x: 50, y: 80, title: "Rear Mounted Turbocharger", details: "The turbo is mounted at the very rear for better chassis weight distribution." } ] } ] }
